                ...selection === undefined ? {} : { agentOptions: { provider: selection.provider, model: selection.model } },
                seed
              });
              session = sessions.get(sessionId);
              published = Boolean(session);
            }
          } catch (error) {
            this.ctx?.logger?.warn?.("dsh-chat: could not publish the room session; falling back to an in-process one", error);
          }
          if (!published) session = sessions.create(sessionId, { meta: { cwd: this.workspacePath }, seed });
        }
        const existingLink = session.events?.find?.((event) => event.type === "chat/room-link");
        if (existingLink && existingLink.data?.roomId !== room.id) throw new Error(`room session ${sessionId} is already linked to another room`);
        if (!existingLink) {
          // 0.2.0 adaptation: a header-only or migrated room session must not brick
          // every later call with "missing its room link" — but do NOT append a
          // make-up event here. Session.append(type, data, ...opts) cannot write the
          // envelope's `ignorable` marker, and dsh-session-persistence's
          // assertEventsSupported() refuses to load a log whose out-of-tree event
          // type lacks it — a made-up event would escalate "one missing event" into
          // "the whole room session log is unreadable". Continue instead; room.sessionId
          // is still recorded, and a later create(seed) rebuilds a properly marked one.
          this.ctx?.logger?.warn?.(`dsh-chat: room session ${sessionId} carries no room link; continuing without it`);
        }
        const titles = this.ctx?.get?.("sessionTitle") ?? this.ctx?.sessionTitle;
        titles?.rename?.(session, room.name);
        room.sessionId = sessionId;
        changed = true;
        await sessions.flush?.(session);
      }
      // 0.2.0 adaptation (temporary diagnostic, removable): our host does not persist
      // plugin logs, so a silent attach failure was invisible. Trace every attach
      // attempt to <dsh-chat>/attach-trace.log, then delete this block once the
      // attach path is understood.
      const traceAttach = async (line) => {
        // Bounded on purpose (peer review): ensureRoomSessions() runs on load, createRoom
        // and acceptInvite, so an unbounded append would grow quietly. Keep the last 200
        // lines only — the file is a temporary diagnostic and gets deleted afterwards.
        try {
          const { readFile, writeFile } = await import("node:fs/promises");
          const file = this.workspacePath + "\\..\\attach-trace.log";
          let kept = "";
          try {
            const lines = (await readFile(file, "utf8")).split("\n").filter((row) => row.length > 0);
            if (lines.length > 0) kept = (lines.length > 199 ? lines.slice(-199) : lines).join("\n") + "\n";
          } catch {}
          await writeFile(file, kept + `${new Date().toISOString()} ${line}\n`);
        } catch {}
      };
      try {
        await traceAttach(`begin room=${room.id} session=${sessionId}`);
        await workspace.attachSession(sessionId);
        await traceAttach(`ok    room=${room.id} session=${sessionId}`);
      } catch (error) {
        await traceAttach(`throw room=${room.id} session=${sessionId} error=${String(error?.message ?? error)}`);
        // 0.2.0 adaptation: this call is UNGATED (it runs for every room) and
        // dsh-workspace refuses an id that session persistence does not hold yet
        // ("cannot validate session '<id>': session persistence holds no such
        // session"). Letting it escape aborts the whole loop BEFORE #save(), so the
        // room ends up with no sessionId at all and never gets an entry in the GUI.
        // Log it and let the remaining rooms — and the save — proceed.
        this.ctx?.logger?.warn?.(("dsh-chat: could not attach room session " + sessionId + " to the Chatrooms workspace"), error);
      }
      // 0.2.0 adaptation (observed 2026-10-11 00:03): the registry can rewrite its table
      // while this attach is in flight — attach returned ok, yet workspace.json ended up
      // with sessionIds=[] for this workspace and the GUI showed no room entry. Verify and
      // retry once; attach is idempotent.
      const attachedIds = Array.isArray(workspace.sessionIds) ? workspace.sessionIds : null;
      if (attachedIds !== null && !attachedIds.includes(sessionId)) {
        await traceAttach(`retry room=${room.id} session=${sessionId} ids=${JSON.stringify(attachedIds)}`);
        await new Promise((resolve) => setTimeout(resolve, 250));
        try {
          await workspace.attachSession(sessionId);
          await traceAttach(`retry-ok room=${room.id} session=${sessionId}`);
        } catch (error) {
          await traceAttach(`retry-throw room=${room.id} error=${String(error?.message ?? error)}`);
        }
      }
    }
    if (changed) await this.#save();
  });
  this.roomSessionTail = operation.catch((error) => {
    // 0.2.0 adaptation: a room-session problem must never block membership or
    // delivery (it used to reject addMember / the invite path).
    this.ctx?.logger?.warn?.("dsh-chat: room session ensure failed", error);
  });
  return this.roomSessionTail;
}

